window.AUTH=window.AUTH||{};window.AUTH["18-315"]={"d":"18-315","id":"2018/18-315","n":"Cochise Consultancy Inc. v. United States, ex rel. Hunt","briefs":[{"k":"petitioner","label":"Brief of petitioner Cochise Consultancy, Inc. and The Parsons Corporation","date":"2019-01-02","url":"https://www.supremecourt.gov/DocketPDF/18/18-315/78026/20190102143440009_Parsons%20Petitioners%20Brief%20TO%20PRINTER.pdf","side":"pet","n":69},{"k":"respondent","label":"Brief of respondent United States of America ex rel. Billy Joe Hunt","date":"2019-02-01","url":"https://www.supremecourt.gov/DocketPDF/18/18-315/86715/20190201155344554_HuntMeritsFinal2-1-19.pdf","side":"res","n":88},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-02-08","url":"https://www.supremecourt.gov/DocketPDF/18/18-315/87681/20190208142752723_18-315bsacUnitedStates.pdf","side":"us","n":62},{"k":"reply","label":"Reply of petitioner Cochise Consultancy, Inc. and The Parsons Corporation","date":"2019-03-04","url":"https://www.supremecourt.gov/DocketPDF/18/18-315/90474/20190304134842713_Parsons%20-%20Petitioners%20Reply%20Brief%20TO%20FILE.pdf","side":"pet","n":27}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/18-315_1b8e.pdf","tr":true,"items":[{"t":"case","label":"Am. Pipe & Constr. Co. v. Utah","cite":"414 U.S. 538","y":1974,"id":"1973/72-1195","sc":1,"sum":"The Court held that commencing a class action suspends all applicable statutes of limitations against members of that class who would have been parties had the suit been allowed to continue as a class action.","sumSrc":"Oyez","by":{"0":"30","2":"26"}},{"t":"case","label":"Arlington Cent. Sch. Dist. Bd. of Educ. v. Murphy","cite":"548 U.S. 291","y":2006,"id":"2005/05-18","sc":1,"sum":"In a 6-to-3 decision authored by Justice Samuel Alito, the Supreme Court held that IDEA did not authorize reimbursement of expert fees. \"While authorizing the award of reasonable attorney's fees, the Act contains detailed provisions that are designed to ensure that such awards are indeed reasonable,\" Justice Alito wrote. \"The absence of any comparable provisions relating to expert fees strongly suggests that recovery of expert fees is not authorized.\" Justice Alito went on to write that the case was made even simpler by the fact that, as an exercise of Congress's Spending Clause power, any provision requiring reimbursement of expert fees would have had to be \"unambiguous,\" which it clearly was not.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"United States ex rel. Becker v. Westinghouse Savannah River Co.","cite":"305 F.3d 284","y":2002,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/305/284/","by":{"0":"34"}},{"t":"case","label":"Bierman v. Int’l Bus. Machs. Corp.","cite":"547 F. App’x 851","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/547/851/","by":{"0":"43"}},{"t":"case","label":"CitiMortgage, Inc. v. Parille","cite":"49 N.E.3d 869","y":2016,"court":"Ill. App. Ct.","url":"https://www.courtlistener.com/c/N.E.3d/49/869/","by":{"0":"44"}},{"t":"case","label":"United States ex rel. Clausen v. Lab. Corp. of Am.","cite":"290 F.3d 1301","y":2002,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/290/1301/","by":{"0":"29"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Credit Suisse Sec. (USA) LLC v. Simmonds","cite":"566 U.S. 221","y":2012,"id":"2011/10-1261","sc":1,"ar":3,"sum":"The Court held that Section 16(b) of the 1934 Securities Exchange Act is subject to tolling, where tolling starts after the filing of a Section 16(a) claim.","sumSrc":"Oyez","by":{"0":"11, 13, 24, 42"}},{"t":"case","label":"CTS Corp. v. Waldburger","cite":"573 U.S. 1","y":2014,"id":"2013/13-339","sc":1,"sum":"The Court found that the Comprehensive Environmental Response, Compensation, and Liability Act pre-empts statutes of limitations, but cannot be used to pre-empt statutes of repose.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Dep’t of Revenue of Or. v. ACF Indus., Inc.","cite":"510 U.S. 332","y":1994,"id":"1993/92-74","sc":1,"sum":"Section 11503 does not limit the States' discretion to exempt nonrailroad property, but not railroad property, from generally applicable ad valorem property taxes.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Dixson v. United States","cite":"465 U.S. 482","y":1984,"id":"1983/82-5279","sc":1,"ar":2,"sum":"Petitioners are \"public officials\". within the meaning of §201(a) and thus are subject to prosecution under the bribery statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41","3":"19, 20"}},{"t":"case","label":"United States ex rel. Eisenstein v. City of New York","cite":"556 U.S. 928","y":2009,"id":"2008/08-660","sc":1,"sum":"The Court held that the 30-day limit for filing a claim under the False Claims Act applies when the United States is not a party to the lawsuit.","sumSrc":"Oyez","by":{"0":"13, 26, 40","1":"6, 40","2":"30"}},{"t":"case","label":"Gabelli v. SEC","cite":"568 U.S. 442","y":2013,"id":"2012/11-1274","sc":1,"ar":5,"sum":"The Court held that a five-year statute of limitations period begins at the time the violation is committed.","sumSrc":"Oyez","by":{"0":"24, 33","1":"32"}},{"t":"case","label":"Glus v. Brooklyn E. Dist. Terminal","cite":"359 U.S. 231","y":1959,"id":"1958/446","sc":1,"sum":"If petitioner can prove that respondent's responsible agents conducted themselves in such a way that he was justifiably misled into a good-faith belief that he could begin his action at any time within seven years after it accrued, he is entitled to have his case tried on the merits, and the District Court erred in dismissing the case on the ground that it was barred by the three-year limitation. Pp. 231-235. 253 F. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Graham Cty. Soil & Water Conservation Dist. v. United States ex rel. Wilson","cite":"545 U.S. 409","y":2005,"id":"2004/04-169","sc":1,"op":2,"sum":"The Court ruled that the six-year statute of limitations did not apply to suits for retaliation. The majority opinion by Justice Clarence Thomas found the statute of limitations \"ambiguous.\" The ambiguity arose from the fact that the six-year limitation in the FCA starts from the time the false claim was made. Yet in a retaliation suit, no actual false claim needs to be alleged.","sumSrc":"Oyez","by":{"0":"3, 5, 9, 10, 11, 12, 13, 14, 15, 16, 17, 19, 20, 21, 22, 23, 25, 26, 35, 39, 40, 42, 43","1":"passim","2":"passim","3":"1, 3, 4, 5, 6, 7, 8, 9, 10, 11, 18, 19"}},{"t":"case","label":"Graham Cty. Soil & Water Conservation Dist. v. United States ex rel. Wilson","cite":"559 U.S. 280","y":2010,"id":"2009/08-304","sc":1,"sum":"The Court held that an audit performed by a state or its political subdivisions constitutes an administrative report within the False Claims Act.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Green v. Brennan","cite":"136 S. Ct. 1769","y":2016,"id":"2015/14-613","sc":1,"sum":"The Court held that the 45-day period in which an employee must file a constructive discharge claim under federal employment discrimination law begins to run on the date the employee resigns.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Hames v. N. Ill. Gas Co.","cite":"388 N.E.2d 1127","y":1979,"court":"Ill. App. Ct.","url":"https://www.courtlistener.com/c/N.E.2d/388/1127/","by":{"0":"24"}},{"t":"case","label":"Holmberg v. Armbrecht","cite":"327 U.S. 392","y":1946,"id":"scdb/1945-049","sc":1,"sum":"1. Decision of a suit in a federal court to enforce a federally created equitable right is not controlled by the statute of limitations of the State of the forum. Guaranty Trust Co. v. York, 326 U. S. 99, distinguished. Accordingly, a class suit by creditors of a joint stock land bank to enforce the liability imposed upon shareholders of the bank by § 16 of the Federal Farm Loan Act is not barred by the state …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"United States ex rel. Hyatt v. Northrop Corp.","cite":"91 F.3d 1211","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/91/1211/","op":1,"by":{"0":"10, 31, 41, 43","1":"15, 61","2":"14, 25","3":"19, 21"}},{"t":"case","label":"Johnson v. Ry. Express Agency, Inc.","cite":"421 U.S. 454","y":1975,"id":"1974/73-1543","sc":1,"sum":"The timely filing of an employment discrimination charge with the Equal Employment Opportunity Commission, pursuant to § 706 of Title VII of the Civil Rights Act of 1964, does not toll the running of the limitation period applicable to an action, based on the same facts, brought under 42 U. S. C. § 1981. Thus, in this case where petitioner waited over 31/2 years after his cause of action for racial employment …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"King v. Burwell","cite":"135 S. Ct. 2480","y":2015,"id":"2014/14-114","sc":1,"sum":"The Court determined that the plain language of the Affordable Care Act extended tax credits to federally-created exchanges as well as those the states created.","sumSrc":"Oyez","by":{"0":"21, 22, 35","1":"27","3":"3"}},{"t":"case","label":"United States ex rel. Kreindler & Kreindler v. United Techs. Corp.","cite":"777 F. Supp. 195","y":1991,"court":"N.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./777/195/","sum":"Holding that knowledge of senior army officials in charge of the project at issue was sufficient to trigger the three-year limitations period.","sumSrc":"brief:0","by":{"0":"33, 44"}},{"t":"case","label":"Liberty Mut. Fire Ins. Co. v. EZ-FLO Int’l, Inc.","cite":"877 F.3d 1081","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/877/1081/","by":{"0":"41"}},{"t":"case","label":"Lozano v. Montoya Alvarez","cite":"572 U.S. 1","y":2014,"id":"2013/12-820","sc":1,"sum":"The Court held that the policy of equitable tolling does not apply to the statute of limitations outlined in the Hauge Convention's provision on international child abduction.","sumSrc":"Oyez","by":{"0":"25","1":"35"}},{"t":"case","label":"United States ex rel. Malloy v. Telephonics Corp.","cite":"68 F. App’x 270","y":2003,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/68/270/","by":{"0":"31"}},{"t":"case","label":"United States ex rel. Marcus v. Hess","cite":"317 U.S. 537","y":1943,"id":"scdb/1942-043","sc":1,"ar":1,"sum":"1. Section 5438 of the Revised Statutes, which subjects to the penalties therein prescribed \"Every person who.. causes to be presented, for payment... any claim upon or against the Government of the United States,... knowing such claim to be.. fraudulent...,\" held applicable to contractors who, by collusive bidding, obtained contracts with municipalities and school districts of a State for work on federal Public …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29","3":"17"}},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"sum":"The Court held that a statute of limitations begins to run once a plaintiff actually discovers -- or a reasonably diligent plaintiff would have discovered -- the facts constituting the violation in the present case, whichever comes first.","sumSrc":"Oyez","by":{"0":"23","2":"23"}},{"t":"case","label":"Pereira v. Sessions","cite":"138 S. Ct. 2105","y":2018,"id":"2017/17-459","sc":1,"sum":"The Court held that a notice to appear for a removal hearing that does not specify the place and time of the hearing does not trigger the stop-time rule of 8 U.S.C. § 1229b(b)(1), which gives the attorney general discretion to cancel removal for an alien who, among other criteria, has been continuously physically present in the country for at least ten years.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Phillips Petroleum Co. v. Lujan","cite":"4 F.3d 858","y":1993,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/4/858/","by":{"0":"33"}},{"t":"case","label":"United States ex rel. Pogue v. Diabetes Treatment Ctrs. of Am., Inc.","cite":"238 F. Supp. 2d 258","y":2002,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/238/258/","by":{"0":"29"}},{"t":"case","label":"Pub. Citizen v. U.S. Dep’t of Justice","cite":"491 U.S. 440","y":1989,"id":"1988/88-429","sc":1,"sum":"To aid the President in fulfilling his constitutional duty to appoint federal judges, the Department of Justice regularly seeks advice from the Standing Committee on Federal Judiciary of the American Bar Association (ABA) regarding potential nominees for judgeships. The ABA Committee's investigations, reports, and votes on potential nominees are kept confidential, although its rating of a particular candidate is …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45","1":"22, 25"}},{"t":"case","label":"Rotella v. Wood","cite":"528 U.S. 549","y":2000,"id":"1999/98-896","sc":1,"sum":"The Court held that Rotella's action was not timely, because the start of the 4-year limitations period applicable to a civil RICO action was not governed by an \"injury and pattern discovery\" accrual rule under which such a civil claim would accrue only when the claimant discovered, or should have discovered, both an injury and a pattern of racketeering activity.","sumSrc":"Oyez","by":{"0":"21, 29"}},{"t":"case","label":"United States ex rel. Sanders v. N. Am. Bus Indus., Inc.","cite":"546 F.3d 288","y":2008,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/546/288/","op":1,"by":{"0":"8, 9, 21, 27, 29, 32, 34","3":"4, 5"}},{"t":"case","label":"SBAM Partners v. Oh","cite":"2004 WL 2580424","y":2004,"court":"Cal. Ct. App. Nov. 12","by":{"0":"44"}},{"t":"case","label":"United States ex rel. Shea v. Verizon Commc’ns, Inc.","cite":"844 F. Supp. 2d 78","y":2012,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/844/78/","by":{"0":"32"}},{"t":"case","label":"United States ex rel. Sikkenga v. Regence Bluecross Blueshield of Utah","cite":"472 F.3d 702","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/472/702/","op":1,"by":{"0":"8, 28, 29","1":"50","3":"8, 17"}},{"t":"case","label":"Silva v. Allstate Ins. Co.","cite":"304 F. App’x 609","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/304/609/","sum":"Holding that an assignee was not entitled to tolling under Hawaii law because he “was aware of the nature of his injuries and failed to pursue his right diligently”.","sumSrc":"brief:0","by":{"0":"43, 44"}},{"t":"case","label":"United States ex rel. Stinson, Lyons, Gerlin & Bustamante, P.A. v. Prudential Ins. Co.","cite":"944 F.2d 1149","y":1991,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/944/1149/","by":{"0":"37"}},{"t":"case","label":"United States v. Borin","cite":"209 F.2d 145","y":1954,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/209/145/","by":{"0":"36"}},{"t":"case","label":"United States v. CFW Constr. Co.","cite":"649 F. Supp. 616","y":1986,"court":"D.S.C.","url":"https://www.courtlistener.com/c/F.%20Supp./649/616/","by":{"0":"24"}},{"t":"case","label":"United States v. Dawes","cite":"151 F.2d 639","y":1945,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/151/639/","by":{"0":"36"}},{"t":"case","label":"United States v. Macomb Contracting Corp.","cite":"763 F. Supp. 272","y":1990,"court":"M.D. Tenn.","url":"https://www.courtlistener.com/c/F.%20Supp./763/272/","sum":"Holding that the Assistant Attorney General in charge of the Civil Division is the only government official whose knowledge would trigger the three-year limitations period.","sumSrc":"brief:0","by":{"0":"33"}},{"t":"case","label":"United States v. Texas","cite":"507 U.S. 529","y":1993,"id":"1992/91-1729","sc":1,"sum":"The Act left in place the States' federal common-law obligation to pay prejudgment interest on debts owed to the Federal Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Universal Health Servs., Inc. v. United States ex rel. Escobar","cite":"136 S. Ct. 1989","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1989/","sc":1,"by":{"0":"3, 34","1":"4, 6, 7, 49","2":"3, 26"}},{"t":"case","label":"Vt. Agency of Natural Res. v. United States ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"op":2,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"0":"13, 40, 43","1":"passim","2":"21, 30","3":"2, 19"}},{"t":"usc","label":"18 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/18/201","subs":["(a)(1)"],"stext":{"head":"§201. Bribery of public officials and witnesses","paras":[[0,"(a) For the purpose of this section—"],[1,"(1) the term \"public official\" means Member of Congress, Delegate, or Resident Commissioner, either before or after such official has qualified, or an officer or employee or person acting for or on behalf of the United States, or any department, agency or branch of Government thereof, including the District of Columbia, in any official function, under or by authority of any such department, agency, or branch of Government, or a juror;"],[1,"(2) the term \"person who has been selected to be a public official\" means any person who has been nominated or appointed to be a public official, or has been officially informed that such person will be so nominated or appointed; and"],[1,"(3) the term \"official act\" means any decision or action on any question, matter, cause, suit, proceeding or controversy, which may at any time be pending, or which may by law be brought before any public official, in such official's official capacity, or in such official's place of trust or profit."],[0,"(b) Whoever—"],[1,"(1) directly or indirectly, corruptly gives, offers or promises anything of value to any public official or person who has been selected to be a public official, or offers or promises any public official or any person who has been selected to be a public official to give anything of value to any other person or entity, with intent—"],[2,"(A) to influence any official act; or"],[2,"(B) to influence such public official or person who has been selected to be a public official to commit or aid in committing, or collude in, or allow, any fraud, or make opportunity for the commission of any fraud, on the United States; or"],[2,"(C) to induce such public official or such person who has been selected to be a public official to do or omit to do any act in violation of the lawful duty of such official or person;"],[1,"(2) being a public official or person selected to be a public official, directly or indirectly, corruptly demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally or for any other person or entity, in return for:"],[2,"(A) being influenced in the performance of any official act;"],[2,"(B) being influenced to commit or aid in committing, or to collude in, or allow, any fraud, or make opportunity for the commission of any fraud, on the United States; or"],[2,"(C) being induced to do or omit to do any act in violation of the official duty of such official or person;"],[1,"(3) directly or indirectly, corruptly gives, offers, or promises anything of value to any person, or offers or promises such person to give anything of value to any other person or entity, with intent to influence the testimony under oath or affirmation of such first-mentioned person as a witness upon a trial, hearing, or other proceeding, before any court, any committee of either House or both Houses of Congress, or any agency, commission, or officer authorized by the laws of the United States to hear evidence or take testimony, or with intent to influence such person to absent himself therefrom;"],[1,"(4) directly or indirectly, corruptly demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally or for any other person or entity in return for being influenced in testimony under oath or affirmation as a witness upon any such trial, hearing, or other proceeding, or in return for absenting himself therefrom;"],[1,"shall be fined under this title or not more than three times the monetary equivalent of the thing of value, whichever is greater, or imprisoned for not more than fifteen years, or both, and may be disqualified from holding any office of honor, trust, or profit under the United States."],[0,"(c) Whoever—"],[1,"(1) otherwise than as provided by law for the proper discharge of official duty—"],[2,"(A) directly or indirectly gives, offers, or promises anything of value to any public official, former public official, or person selected to be a public official, for or because of any official act performed or to be performed by such public official, former public official, or person selected to be a public official; or"],[2,"(B) being a public official, former public official, or person selected to be a public official, otherwise than as provided by law for the proper discharge of official duty, directly or indirectly demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally for or because of any official act performed or to be performed by such official or person;"],[1,"(2) directly or indirectly, gives, offers, or promises anything of value to any person, for or because of the testimony under oath or affirmation given or to be given by such person as a witness upon a trial, hearing, or other proceeding, before any court, any committee of either House or both Houses of Congress, or any agency, commission, or officer authorized by the laws of the United States to hear evidence or take testimony, or for or because of such person's absence therefrom;"],[1,"(3) directly or indirectly, demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally for or because of the testimony under oath or affirmation given or to be given by such person as a witness upon any such trial, hearing, or other proceeding, or for or because of such person's absence therefrom;"],[1,"shall be fined under this title or imprisoned for not more than two years, or both."],[0,"(d) Paragraphs (3) and (4) of subsection (b) and paragraphs (2) and (3) of subsection (c) shall not be construed to prohibit the payment or receipt of witness fees provided by law, or the payment, by the party upon whose behalf a witness is called and receipt by a witness, of the reasonable cost of travel and subsistence incurred and the reasonable value of time lost in attendance at any such trial, hearing, or proceeding, or in the case of expert witnesses, a reasonable fee for time spent in the preparation of such opinion, and in appearing and testifying."],[0,"(e) The offenses and penalties prescribed in this section are separate from and in addition to those prescribed in sections 1503, 1504, and 1505 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/201?type=usc&year=mostrecent&link-type=html"},"head":"§201. Bribery of public officials and witnesses","tname":"Crimes and Criminal Procedure","by":{"0":"41","1":"58"}},{"t":"usc","label":"18 U.S.C. § 287","url":"https://www.law.cornell.edu/uscode/text/18/287","by":{"0":"30"}},{"t":"usc","label":"18 U.S.C. § 3282","url":"https://www.law.cornell.edu/uscode/text/18/3282","by":{"0":"30"}},{"t":"usc","label":"28 U.S.C. § 2415","url":"https://www.law.cornell.edu/uscode/text/28/2415","stext":{"head":"§2415. Time for commencing actions brought by the United States","paras":[[0,"(a) Subject to the provisions of section 2416 of this title, and except as otherwise provided by Congress, every action for money damages brought by the United States or an officer or agency thereof which is founded upon any contract express or implied in law or fact, shall be barred unless the complaint is filed within six years after the right of action accrues or within one year after final decisions have been rendered in applicable administrative proceedings required by contract or by law, whichever is later: Provided, That in the event of later partial payment or written acknowledgment of debt, the right of action shall be deemed to accrue again at the time of each such payment or acknowledgment: Provided further, That an action for money damages brought by the United States for or on behalf of a recognized tribe, band or group of American Indians shall not be barred unless the complaint is filed more than six years and ninety days after the right of action accrued: Provided further, That an action for money damages which accrued on the date of enactment of this Act in accordance with subsection (g) brought by the United States for or on behalf of a recognized tribe, band, or group of American Indians, or on behalf of an individual Indian whose land is held in trust or restricted status, shall not be barred unless the complaint is filed sixty days after the date of publication of the list required by section 4(c) of the Indian Claims Limitation Act of 1982: Provided, That, for those claims that are on either of the two lists published pursuant to the Indian Claims Limitation Act of 1982, any right of action shall be barred unless the complaint is filed within (1) one year after the Secretary of the Interior has published in the Federal Register a notice rejecting such claim or (2) three years after the date the Secretary of the Interior has submitted legislation or legislative report to Congress to resolve such claim or more than two years after a final decision has been rendered in applicable administrative proceedings required by contract or by law, whichever is later."],[0,"(b) Subject to the provisions of section 2416 of this title, and except as otherwise provided by Congress, every action for money damages brought by the United States or an officer or agency thereof which is founded upon a tort shall be barred unless the complaint is filed within three years after the right of action first accrues: Provided, That an action to recover damages resulting from a trespass on lands of the United States; an action to recover damages resulting from fire to such lands; an action to recover for diversion of money paid under a grant program; and an action for conversion of property of the United States may be brought within six years after the right of action accrues, except that such actions for or on behalf of a recognized tribe, band or group of American Indians, including actions relating to allotted trust or restricted Indian lands, may be brought within six years and ninety days after the right of action accrues, except that such actions for or on behalf of a recognized tribe, band, or group of American Indians, including actions relating to allotted trust or restricted Indian lands, or on behalf of an individual Indian whose land is held in trust or restricted status which accrued on the date of enactment of this Act in accordance with subsection (g) may be brought on or before sixty days after the date of the publication of the list required by section 4(c) of the Indian Claims Limitation Act of 1982: Provided, That, for those claims that are on either of the two lists published pursuant to the Indian Claims Limitation Act of 1982, any right of action shall be barred unless the complaint is filed within (1) one year after the Secretary of the Interior has published in the Federal Register a notice rejecting such claim or (2) three years after the Secretary of the Interior has submitted legislation or legislative report to Congress to resolve such claim."],[0,"(c) Nothing herein shall be deemed to limit the time for bringing an action to establish the title to, or right of possession of, real or personal property."],[0,"(d) Subject to the provisions of section 2416 of this title and except as otherwise provided by Congress, every action for the recovery of money erroneously paid to or on behalf of any civilian employee of any agency of the United States or to or on behalf of any member or dependent of any member of the uniformed services of the United States, incident to the employment or services of such employee or member, shall be barred unless the complaint is filed within six years after the right of action accrues: Provided, That in the event of later partial payment or written acknowledgment of debt, the right of action shall be deemed to accrue again at the time of each such payment or acknowledgment."],[0,"(e) In the event that any action to which this section applies is timely brought and is thereafter dismissed without prejudice, the action may be recommenced within one year after such dismissal, regardless of whether the action would otherwise then be barred by this section. In any action so recommenced the defendant shall not be barred from interposing any claim which would not have been barred in the original action."],[0,"(f) The provisions of this section shall not prevent the assertion, in an action against the United States or an officer or agency thereof, of any claim of the United States or an officer or agency thereof against an opposing party, a co-party, or a third party that arises out of the transaction or occurrence that is the subject matter of the opposing party's claim. A claim of the United States or an officer or agency thereof that does not arise out of the transaction or occurrence that is the subject matter of the opposing party's claim may, if time-barred, be asserted only by way of offset and may be allowed in an amount not to exceed the amount of the opposing party's recovery."],[0,"(g) Any right of action subject to the provisions of this section which accrued prior to the date of enactment of this Act shall, for purposes of this section, be deemed to have accrued on the date of enactment of this Act."],[0,"(h) Nothing in this Act shall apply to actions brought under the Internal Revenue Code or incidental to the collection of taxes imposed by the United States."],[0,"(i) The provisions of this section shall not prevent the United States or an officer or agency thereof from collecting any claim of the United States by means of administrative offset, in accordance with section 3716 of title 31."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2415?type=usc&year=mostrecent&link-type=html"},"head":"§2415. Time for commencing actions brought by the United States","tname":"Judiciary and Judicial Procedure","by":{"0":"20, 35, 36","1":"47","2":"19"}},{"t":"usc","label":"28 U.S.C. § 2416","url":"https://www.law.cornell.edu/uscode/text/28/2416","subs":["(c)"],"stext":{"head":"§2416. Time for commencing actions brought by the United States—Exclusions","paras":[[0,"For the purpose of computing the limitations periods established in section 2415, there shall be excluded all periods during which—"],[1,"(a) the defendant or the res is outside the United States, its territories and possessions, the District of Columbia, or the Commonwealth of Puerto Rico; or"],[1,"(b) the defendant is exempt from legal process because of infancy, mental incompetence, diplomatic immunity, or for any other reason; or"],[1,"(c) facts material to the right of action are not known and reasonably could not be known by an official of the United States charged with the responsibility to act in the circumstances; or"],[1,"(d) the United States is in a state of war declared pursuant to article I, section 8, of the Constitution of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2416?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§2416. Time for commencing actions brought by the United States—Exclusions","tname":"Judiciary and Judicial Procedure","by":{"0":"2, 5, 20, 35","1":"47","2":"19, 18, 19","3":"5, 18"}},{"t":"usc","label":"31 U.S.C. § 3729","url":"https://www.law.cornell.edu/uscode/text/31/3729","subs":["(a)","(a)(2)","(b)","(b)(1)","(a)(1)","(a)(2)(A)","(a)(2)(B)"],"stext":{"head":"§3729. False claims","paras":[[0,"(a) Liability for Certain Acts.—"],[1,"(1) In general.—Subject to paragraph (2), any person who—"],[2,"(A) knowingly presents, or causes to be presented, a false or fraudulent claim for payment or approval;"],[2,"(B) knowingly makes, uses, or causes to be made or used, a false record or statement material to a false or fraudulent claim;"],[2,"(C) conspires to commit a violation of subparagraph (A), (B), (D), (E), (F), or (G);"],[2,"(D) has possession, custody, or control of property or money used, or to be used, by the Government and knowingly delivers, or causes to be delivered, less than all of that money or property;"],[2,"(E) is authorized to make or deliver a document certifying receipt of property used, or to be used, by the Government and, intending to defraud the Government, makes or delivers the receipt without completely knowing that the information on the receipt is true;"],[2,"(F) knowingly buys, or receives as a pledge of an obligation or debt, public property from an officer or employee of the Government, or a member of the Armed Forces, who lawfully may not sell or pledge property; or"],[2,"(G) knowingly makes, uses, or causes to be made or used, a false record or statement material to an obligation to pay or transmit money or property to the Government, or knowingly conceals or knowingly and improperly avoids or decreases an obligation to pay or transmit money or property to the Government,"],[1,"is liable to the United States Government for a civil penalty of not less than $5,000 and not more than $10,000, as adjusted by the Federal Civil Penalties Inflation Adjustment Act of 1990 (28 U.S.C. 2461 note; Public Law 104–410 1), plus 3 times the amount of damages which the Government sustains because of the act of that person."],[1,"(2) Reduced damages.—If the court finds that—"],[2,"(A) the person committing the violation of this subsection furnished officials of the United States responsible for investigating false claims violations with all information known to such person about the violation within 30 days after the date on which the defendant first obtained the information;"],[2,"(B) such person fully cooperated with any Government investigation of such violation; and"],[2,"(C) at the time such person furnished the United States with the information about the violation, no criminal prosecution, civil action, or administrative action had commenced under this title with respect to such violation, and the person did not have actual knowledge of the existence of an investigation into such violation,"],[1,"the court may assess not less than 2 times the amount of damages which the Government sustains because of the act of that person."],[1,"(3) Costs of civil actions.—A person violating this subsection shall also be liable to the United States Government for the costs of a civil action brought to recover any such penalty or damages."],[0,"(b) Definitions.—For purposes of this section—"],[1,"(1) the terms \"knowing\" and \"knowingly\"—"],[2,"(A) mean that a person, with respect to information—"],[3,"(i) has actual knowledge of the information;"],[3,"(ii) acts in deliberate ignorance of the truth or falsity of the information; or"],[3,"(iii) acts in reckless disregard of the truth or falsity of the information; and"],[2,"(B) require no proof of specific intent to defraud;"],[1,"(2) the term \"claim\"—"],[2,"(A) means any request or demand, whether under a contract or otherwise, for money or property and whether or not the United States has title to the money or property, that—"],[3,"(i) is presented to an officer, employee, or agent of the United States; or"],[3,"(ii) is made to a contractor, grantee, or other recipient, if the money or property is to be spent or used on the Government's behalf or to advance a Government program or interest, and if the United States Government—"],[4,"(I) provides or has provided any portion of the money or property requested or demanded; or"],[4,"(II) will reimburse such contractor, grantee, or other recipient for any portion of the money or property which is requested or demanded; and"],[2,"(B) does not include requests or demands for money or property that the Government has paid to an individual as compensation for Federal employment or as an income subsidy with no restrictions on that individual's use of the money or property;"],[1,"(3) the term \"obligation\" means an established duty, whether or not fixed, arising from an express or implied contractual, grantor-grantee, or licensor-licensee relationship, from a fee-based or similar relationship, from statute or regulation, or from the retention of any overpayment; and"],[1,"(4) the term \"material\" means having a natural tendency to influence, or be capable of influencing, the payment or receipt of money or property."],[0,"(c) Exemption From Disclosure.—Any information furnished pursuant to subsection (a)(2) shall be exempt from disclosure under section 552 of title 5."],[0,"(d) Exclusion.—This section does not apply to claims, records, or statements made under the Internal Revenue Code of 1986."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3729?type=usc&year=mostrecent&link-type=html"},"op":7,"ar":1,"head":"§3729. False claims","tname":"Money and Finance","by":{"0":"4","1":"6, 59, 49, 60, 9, 6, passim","2":"1, 2, 9, 16, 20, 21, 1, 2, 29, 29"}},{"t":"usc","label":"31 U.S.C. § 3730","url":"https://www.law.cornell.edu/uscode/text/31/3730","subs":["(a)","(b)(1)","(b)(2)","(c)(2)(A)","(c)(3)","(d)","(e)(3)","(e)(4)","(b)","(b)(3)","(b)(4)","(b)(5)","(c)","(c)(1)","(c)(2)","(c)(2)(B)","(c)(2)(C)","(c)(2)(D)(3)","(c)(4)","(d)(1)","(d)(2)","(e)(4)(A)","(e)(4)(B)","(h)","(2000)","(b)(4)(A)","(b)(4)(B)","(e)(2)(A)","(h)(2000)","(h)(3)"],"stext":{"head":"§3730. Civil actions for false claims","paras":[[0,"(a) Responsibilities of the Attorney General.—The Attorney General diligently shall investigate a violation under section 3729. If the Attorney General finds that a person has violated or is violating section 3729, the Attorney General may bring a civil action under this section against the person."],[0,"(b) Actions by Private Persons.—(1) A person may bring a civil action for a violation of section 3729 for the person and for the United States Government. The action shall be brought in the name of the Government. The action may be dismissed only if the court and the Attorney General give written consent to the dismissal and their reasons for consenting."],[0,"(2) A copy of the complaint and written disclosure of substantially all material evidence and information the person possesses shall be served on the Government pursuant to Rule 4(d)(4) 1 of the Federal Rules of Civil Procedure. The complaint shall be filed in camera, shall remain under seal for at least 60 days, and shall not be served on the defendant until the court so orders. The Government may elect to intervene and proceed with the action within 60 days after it receives both the complaint and the material evidence and information."],[0,"(3) The Government may, for good cause shown, move the court for extensions of the time during which the complaint remains under seal under paragraph (2). Any such motions may be supported by affidavits or other submissions in camera. The defendant shall not be required to respond to any complaint filed under this section until 20 days after the complaint is unsealed and served upon the defendant pursuant to Rule 4 of the Federal Rules of Civil Procedure."],[0,"(4) Before the expiration of the 60-day period or any extensions obtained under paragraph (3), the Government shall—"],[1,"(A) proceed with the action, in which case the action shall be conducted by the Government; or"],[1,"(B) notify the court that it declines to take over the action, in which case the person bringing the action shall have the right to conduct the action."],[0,"(5) When a person brings an action under this subsection, no person other than the Government may intervene or bring a related action based on the facts underlying the pending action."],[0,"(c) Rights of the Parties to Qui Tam Actions.—(1) If the Government proceeds with the action, it shall have the primary responsibility for prosecuting the action, and shall not be bound by an act of the person bringing the action. Such person shall have the right to continue as a party to the action, subject to the limitations set forth in paragraph (2)."],[0,"(2)(A) The Government may dismiss the action notwithstanding the objections of the person initiating the action if the person has been notified by the Government of the filing of the motion and the court has provided the person with an opportunity for a hearing on the motion."],[0,"(B) The Government may settle the action with the defendant notwithstanding the objections of the person initiating the action if the court determines, after a hearing, that the proposed settlement is fair, adequate, and reasonable under all the circumstances. Upon a showing of good cause, such hearing may be held in camera."],[0,"(C) Upon a showing by the Government that unrestricted participation during the course of the litigation by the person initiating the action would interfere with or unduly delay the Government's prosecution of the case, or would be repetitious, irrelevant, or for purposes of harassment, the court may, in its discretion, impose limitations on the person's participation, such as—"],[1,"(i) limiting the number of witnesses the person may call;"],[1,"(ii) limiting the length of the testimony of such witnesses;"],[1,"(iii) limiting the person's cross-examination of witnesses; or"],[1,"(iv) otherwise limiting the participation by the person in the litigation."],[0,"(D) Upon a showing by the defendant that unrestricted participation during the course of the litigation by the person initiating the action would be for purposes of harassment or would cause the defendant undue burden or unnecessary expense, the court may limit the participation by the person in the litigation."],[0,"(3) If the Government elects not to proceed with the action, the person who initiated the action shall have the right to conduct the action. If the Government so requests, it shall be served with copies of all pleadings filed in the action and shall be supplied with copies of all deposition transcripts (at the Government's expense). When a person proceeds with the action, the court, without limiting the status and rights of the person initiating the action, may nevertheless permit the Government to intervene at a later date upon a showing of good cause."],[0,"(4) Whether or not the Government proceeds with the action, upon a showing by the Government that certain actions of discovery by the person initiating the action would interfere with the Government's investigation or prosecution of a criminal or civil matter arising out of the same facts, the court may stay such discovery for a period of not more than 60 days. Such a showing shall be conducted in camera. The court may extend the 60-day period upon a further showing in camera that the Government has pursued the criminal or civil investigation or proceedings with reasonable diligence and any proposed discovery in the civil action will interfere with the ongoing criminal or civil investigation or proceedings."],[0,"(5) Notwithstanding subsection (b), the Government may elect to pursue its claim through any alternate remedy available to the Government, including any administrative proceeding to determine a civil money penalty. If any such alternate remedy is pursued in another proceeding, the person initiating the action shall have the same rights in such proceeding as such person would have had if the action had continued under this section. Any finding of fact or conclusion of law made in such other proceeding that has become final shall be conclusive on all parties to an action under this section. For purposes of the preceding sentence, a finding or conclusion is final if it has been finally determined on appeal to the appropriate court of the United States, if all time for filing such an appeal with respect to the finding or conclusion has expired, or if the finding or conclusion is not subject to judicial review."],[0,"(d) Award to Qui Tam Plaintiff.—(1) If the Government proceeds with an action brought by a person under subsection (b), such person shall, subject to the second sentence of this paragraph, receive at least 15 percent but not more than 25 percent of the proceeds of the action or settlement of the claim, depending upon the extent to which the person substantially contributed to the prosecution of the action. Where the action is one which the court finds to be based primarily on disclosures of specific information (other than information provided by the person bringing the action) relating to allegations or transactions in a criminal, civil, or administrative hearing, in a congressional, administrative, or Government 2 Accounting Office report, hearing, audit, or investigation, or from the news media, the court may award such sums as it considers appropriate, but in no case more than 10 percent of the proceeds, taking into account the significance of the information and the role of the person bringing the action in advancing the case to litigation. Any payment to a person under the first or second sentence of this paragraph shall be made from the proceeds. Any such person shall also receive an amount for reasonable expenses which the court finds to have been necessarily incurred, plus reasonable attorneys' fees and costs. All such expenses, fees, and costs shall be awarded against the defendant."],[0,"(2) If the Government does not proceed with an action under this section, the person bringing the action or settling the claim shall receive an amount which the court decides is reasonable for collecting the civil penalty and damages. The amount shall be not less than 25 percent and not more than 30 percent of the proceeds of the action or settlement and shall be paid out of such proceeds. Such person shall also receive an amount for reasonable expenses which the court finds to have been necessarily incurred, plus reasonable attorneys' fees and costs. All such expenses, fees, and costs shall be awarded against the defendant."],[0,"(3) Whether or not the Government proceeds with the action, if the court finds that the action was brought by a person who planned and initiated the violation of section 3729 upon which the action was brought, then the court may, to the extent the court considers appropriate, reduce the share of the proceeds of the action which the person would otherwise receive under paragraph (1) or (2) of this subsection, taking into account the role of that person in advancing the case to litigation and any relevant circumstances pertaining to the violation. If the person bringing the action is convicted of criminal conduct arising from his or her role in the violation of section 3729, that person shall be dismissed from the civil action and shall not receive any share of the proceeds of the action. Such dismissal shall not prejudice the right of the United States to continue the action, represented by the Department of Justice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3730?type=usc&year=mostrecent&link-type=html"},"op":22,"ar":13,"head":"§3730. Civil actions for false claims","tname":"Money and Finance","by":{"0":"4, 2, 4, 13, 27, 40, 4, 27, 40, 4, 27, 27","1":"5, 21, 29, 59, 5, 6, 9, 21, 28, 29, 30, 3, 29, 30, 55, 29, 5, 29, 7, 53, 62, 9, 28, 59, 5, 29, 44, 46, 46, 5, 29, 44, 5, 44, 46, 5, 29, 9, 6, 29, 36, 38, 47, 29, 28, 54, 6, 45, 46, 6, 9, 46, 7, 53, 62, 7, 53, 62, 21, 46","2":"15, 14, 15, 18, 2, 27, 28, passim, 2, 21, 28, 31, 2, 21, 24, 14, 21, 2, 2,14, 21, 2, 25, 21, 31, 22, 2, 14, 21, 22, 31, 2, 26, 31, 3, 26, 31, 22, 25, 25, 22, 15, 7, 9, 15, 16, 15","3":"20, 21, 19, 12, 21"}},{"t":"usc","label":"31 U.S.C. § 3731","url":"https://www.law.cornell.edu/uscode/text/31/3731","subs":["(b)","(b)(1)","(b)(2)","(d)","(c)","(b)(1982)","(c)(2000)"],"stext":{"head":"§3731. False claims procedure","paras":[[0,"(a) A subpena requiring the attendance of a witness at a trial or hearing conducted under section 3730 of this title may be served at any place in the United States."],[0,"(b) A civil action under section 3730 may not be brought—"],[1,"(1) more than 6 years after the date on which the violation of section 3729 is committed, or"],[1,"(2) more than 3 years after the date when facts material to the right of action are known or reasonably should have been known by the official of the United States charged with responsibility to act in the circumstances, but in no event more than 10 years after the date on which the violation is committed,"],[0,"whichever occurs last."],[0,"(c) If the Government elects to intervene and proceed with an action brought under 3730(b),1 the Government may file its own complaint or amend the complaint of a person who has brought an action under section 3730(b) to clarify or add detail to the claims in which the Government is intervening and to add any additional claims with respect to which the Government contends it is entitled to relief. For statute of limitations purposes, any such Government pleading shall relate back to the filing date of the complaint of the person who originally brought the action, to the extent that the claim of the Government arises out of the conduct, transactions, or occurrences set forth, or attempted to be set forth, in the prior complaint of that person."],[0,"(d) In any action brought under section 3730, the United States shall be required to prove all essential elements of the cause of action, including damages, by a preponderance of the evidence."],[0,"(e) Notwithstanding any other provision of law, the Federal Rules of Criminal Procedure, or the Federal Rules of Evidence, a final judgment rendered in favor of the United States in any criminal proceeding charging fraud or false statements, whether upon a verdict after trial or upon a plea of guilty or nolo contendere, shall estop the defendant from denying the essential elements of the offense in any action which involves the same transaction as in the criminal proceeding and which is brought under subsection (a) or (b) of section 3730."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3731?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3731. False claims procedure","tname":"Money and Finance","by":{"0":"1, 4, 2, 2, 5, 10, 13, 14, 18, 25, 32, 40, 41, 47, 10, 19","1":"passim, 3, 13, passim, 5, 9, 18, 33, 39, 29","2":"3, passim, passim, passim, 18, 17, 18","3":"1, 13"}},{"t":"law","label":"Pub. L. No. 97-258","url":"https://www.govinfo.gov/link/statute/96/877","by":{"0":"4"}},{"t":"law","label":"Pub. L. No. 99-562","url":"https://www.govinfo.gov/link/statute/100/3153","by":{"0":"4","2":"3, 23"}},{"t":"law","label":"Pub. L. No. 111-21","url":"https://www.govinfo.gov/link/plaw/111/public/21","by":{"0":"19","1":"33"}},{"t":"reg","label":"28 C.F.R. § 85.3","url":"https://www.ecfr.gov/current/title-28/section-85.3","subs":["(a)(9)"],"by":{"0":"4"}},{"t":"case","label":"Barnhart v. Sigmon Coal Co., Inc.","cite":"534 U.S. 438","y":2002,"id":"2001/00-1307","sc":1,"op":1,"ar":1,"sum":"The Court held that the Act did not permit the Commissioner to assign retired miners to the successors in interest of out-of-business signatory operators, since the companies were not related to such operators under the Act's statutory definitions.","sumSrc":"Oyez","by":{"1":"20, 24"}},{"t":"case","label":"Caminetti v. United States","cite":"242 U.S. 470","y":1917,"id":"scdb/1916-190","sc":1,"sum":"The White Slave Traffic Act of June 25, 1910, c. 395, 36 Stat. 825, applies to any case in which a woman is transported in interstate commerce for the purpose of prostitution or concubinage; pecuniary gain, either as a motive for the transportation or as an attendant of its object, is not an element in the offenses defined.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Chung Fook v. White","cite":"264 U.S. 443","y":1924,"id":"scdb/1923-107","sc":1,"sum":"The proviso of § 22 of the Immigration Act of February 5, 1917, under which the wife of a \"naturalized\" citizen, married to him after his naturalization and sent for by him, may be admitted without detention for treatment in hospital though found to be affected with a contagious disorder, cannot be extended by judicial construction to include the wife of a native born citizen. P. 445. 287 Fed. 533, affirmed. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Cook Cnty. v. United States ex rel. Chandler","cite":"538 U.S. 119","y":2003,"id":"2002/01-1572","sc":1,"sum":"The Court held that the term \"person\" includes local governments. The Court noted that the County, as a recipient of federal funding, was clearly able to abuse federal spending and was thus subject to the FCA remedy that applied to prevent such abuse.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Crooks v. Harrelson","cite":"282 U.S. 55","y":1930,"id":"scdb/1930-011","sc":1,"sum":"that the requirements that a property interest, to be included, shall be subject to the payment of the charges against the estate and the expenses of administration must be taken, as they are expressed, in the conjunctive; that charges against the estate and expenses of administration are different and distinct things, and that when, by the state law, an interest in real estate, though subject to the former, is not …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22, 23"}},{"t":"case","label":"Culbertson v. Berryhill, ___ S. Ct. ___","cite":"2019 WL 122163","y":2019,"court":"Jan. 8","sum":"Stating the Court “begi[ns] with the language of the statute itself, and that is also where the inquiry should end” when the “statute’s language is plain”.","sumSrc":"brief:1","by":{"1":"20"}},{"t":"case","label":"Desert Palace, Inc. v. Costa","cite":"539 U.S. 90","y":2003,"id":"2002/02-679","sc":1,"sum":"The Court held that direct evidence is not required.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Envtl. Def. v. Duke Energy Corp.","cite":"549 U.S. 561","y":2007,"id":"2006/05-848","sc":1,"sum":"Unanswered and No. In a unanimous opinion by Justice David Souter, the Court ruled that the EPA need not interpret \"modification\" in PSD regulations the same way the term is interpreted in NSPS regulations. The Court's opinion acknowledged that two occurrences of the same term - sharing the same definition - are normally given the same meaning.","sumSrc":"Oyez","by":{"1":"60","3":"2, 6"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"op":2,"sum":"The Court ruled that as long one plaintiff meets the amount-in-controversy requirement for federal jurisdiction, Section 1367 authorizes federal courts to exercise supplemental jurisdiction over related claims even if they do not meet the requirement.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"FBI v. Abramson","cite":"456 U.S. 615","y":1982,"id":"1981/80-1735","sc":1,"sum":"Information contained in records originally compiled for law enforcement purposes does not lose its Exemption 7 exemption where such information is reproduced or summarized in a new document prepared for other than law enforcement purposes, but continues to meet Exemption 7's threshold requirement of being compiled for law enforcement purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26, 54"}},{"t":"case","label":"Greyhound Corp. v. Mt. Hood States, Inc.","cite":"437 U.S. 322","y":1978,"id":"1977/77-598","sc":1,"sum":"The Clayton Act's statute of limitations was GREYHOUND CORP. v. MT. HOOD STAGES, INC. not tolled under § 5 (i) by the filing of the Government's petition to intervene in the ICC proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35, 39"}},{"t":"case","label":"Hagood v. Sonoma Cty. Water Agency","cite":"81 F.3d 1465","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/81/1465/","by":{"1":"29"}},{"t":"case","label":"Holy Trinity Church v. United States","cite":"143 U.S. 457","y":1892,"id":"scdb/1891-129","sc":1,"sum":"The act of February 26, 1885, “ to prohibit the importation and migration of foreigners and aliens under contract.or agreement to perform labor in the United States, its Territories, and the District of Columbia,” 23 Stat. 332, c. 164, does not apply to a contract between an alien, residing out of the United States, and a religious society incorporated under the laws of a State,' whereby he engages to remove to the …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Husky Int’l Elecs. v. Ritz","cite":"136 S. Ct. 1581","y":2016,"id":"2015/15-145","sc":1,"sum":"The Court determined that the “actual fraud” language of the bankruptcy statute encompasses traditional forms of fraud and is not limited to fraudulent representation.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Kellogg Brown & Root Servs. v. United States ex rel. Carter","cite":"135 S. Ct. 1970","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1970/","sc":1,"by":{"1":"4"}},{"t":"case","label":"Lamie v. United States Tr.","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"1":"49"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Solem v. Bartlett","cite":"465 U.S. 463","y":1984,"id":"1983/82-1253","sc":1,"sum":"The Act did not diminish the reservation.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"State Farm Fire & Cas. Co. v. United States ex rel. Rigsby","cite":"137 S. Ct. 436","y":2011,"id":"2016/15-513","sc":1,"sum":"The Court determined that a violation of the False Claims Act’s seal requirement does not mandate dismissal of the complaint.","sumSrc":"Oyez","by":{"1":"41, 43, 46"}},{"t":"case","label":"Treat v. White","cite":"181 U.S. 264","y":1901,"id":"scdb/1900-167","sc":1,"sum":"What is denominated “ a call,” in the language of New York stock brokers, is an agreement to sell, and3 as the statutes of the United States in force in May, 1899,’ required stamps to bo affixed on all sales or agreements to sell, the calls were within its provisions.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"20, 23, 24"}},{"t":"case","label":"Unexcelled Chem. Corp. v. United States","cite":"345 U.S. 59","y":1953,"id":"scdb/1952-056","sc":1,"sum":"1. An action brought by the United States under the Walsh-Healey Act to recover liquidated damages from a government contractor who knowingly employed child labor in violation of the Act is subject to the two-year statute of limitations contained in § 6 of the Portal-to-Portal Act of 1947.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22, 26, 54, 56"}},{"t":"case","label":"United States ex rel. Absher v. Momence Meadows Nursing Ctr., Inc.","cite":"764 F.3d 699","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/764/699/","by":{"1":"29"}},{"t":"case","label":"United States ex rel. Atkins v. McInteer","cite":"470 F.3d 1350","y":2006,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/470/1350/","by":{"1":"44"}},{"t":"case","label":"United States ex rel. Costa v. Baker & Taylor, Inc.","cite":"955 F. Supp. 1188","y":1997,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./955/1188/","by":{"1":"56"}},{"t":"case","label":"United States ex rel. DeCarlo v. Kiewit/AFC Enters.","cite":"937 F. Supp. 1039","y":1996,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./937/1039/","by":{"1":"54"}},{"t":"case","label":"United States ex rel. Lujan v. Hughes Aircraft Co.","cite":"162 F.3d 1027","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/162/1027/","by":{"1":"47"}},{"t":"case","label":"United States ex rel. Milam v. Univ. of Tex. M.D. Anderson Cancer Ctr.","cite":"961 F.2d 46","y":1992,"url":"https://www.courtlistener.com/c/F.2d/961/46/","by":{"1":"41"}},{"t":"case","label":"United States ex rel. Springfield Terminal Ry. v. Quinn","cite":"14 F.3d 645","y":1994,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/14/645/","by":{"1":"54"}},{"t":"case","label":"United States ex rel. Ubl v. IIF Data Sols.","cite":"650 F.3d 445","y":2011,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/650/445/","by":{"1":"37"}},{"t":"case","label":"United States ex rel. Williams v. NEC Corp.","cite":"931 F.2d 1493","y":1991,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/931/1493/","by":{"1":"45"}},{"t":"case","label":"United States v. Baylor Univ. Med. Ctr.","cite":"469 F.3d 263","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/469/263/","by":{"1":"33, 55"}},{"t":"case","label":"United States v. Bornstein","cite":"423 U.S. 303","y":1976,"id":"1975/74-712","sc":1,"sum":"A prime contractor (Model) had a contract with the Government to provide radio kits containing electron tubes meeting certain specifications. A subcontractor (United), which was to supply the tubes, sent to Model in three separately invoiced shipments tubes that were not of the required quality but were falsely marked to indicate that they were. The radio kits that Model in turn shipped to the Government contained …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"8","2":"3"}},{"t":"case","label":"United States v. General Elec.","cite":"808 F. Supp. 580","y":1992,"court":"S.D. Ohio","url":"https://www.courtlistener.com/c/F.%20Supp./808/580/","by":{"1":"54","3":"15"}},{"t":"case","label":"United States v. Griswold","cite":"24 F. 361","y":1885,"court":"D. Oregon","url":"https://www.courtlistener.com/c/F./24/361/","by":{"1":"50"}},{"t":"case","label":"United States v. Ron Pair Enters., Inc.","cite":"489 U.S. 235","y":1989,"id":"1988/87-1043","sc":1,"sum":"Section 506(b) entitles a creditor to receive postpetition interest on a nonconsensual oversecured claim allowed in a bankruptcy proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22, 25"}},{"t":"case","label":"Wallace v. Kato","cite":"549 U.S. 384","y":2007,"id":"2006/05-1240","sc":1,"sum":"The opinion by Justice Antonin Scalia held that \"the statute of limitations begins to run when the alleged false imprisonment ends.\" Since false imprisonment is detention without legal process, the Court ruled, the false imprisonment ends when legal processes begin. At that point, the clock begins to run on the time limit for filing a false imprisonment claim.","sumSrc":"Oyez","by":{"1":"37","3":"11"}},{"t":"const","label":"Article II, Section 3","clauses":[["take-care","Take Care Clause"]],"text":"He shall from time to time give to the Congress Information of the State of the Union, and recommend to their Consideration such Measures as he shall judge necessary and expedient; he may, on extraordinary Occasions, convene both Houses, or either of them, and in Case of Disagreement between them, with Respect to the Time of Adjournment, he may adjourn them to such Time as he shall think proper; he shall receive Ambassadors and other public Ministers; he shall take Care that the Laws be faithfully executed, and shall Commission all the Officers of the United States.","by":{"1":"59"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"1":"1"}},{"t":"usc","label":"31 U.S.C. § 232","url":"https://www.law.cornell.edu/uscode/text/31/232","subs":["(C)"],"by":{"1":"9"}},{"t":"reg","label":"15 C.F.R. § 6.3","url":"https://www.ecfr.gov/current/title-15/section-6.3","subs":["(3)"],"by":{"1":"6"}},{"t":"case","label":"Bankamerica Corp. v. United States","cite":"462 U.S. 122","y":1983,"id":"1982/81-1487","sc":1,"sum":"The fourth paragraph of § 8 does not bar interlocking directorates between a bank and a competing insurance company.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17"}},{"t":"case","label":"Bierman v. International Bus. Machs. Corp.","cite":"547 Fed. Appx. 851","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./547/851/","by":{"2":"30"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"2":"17","3":"6"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"John Beaudette, Inc. v. Sentry Ins. A Mut. Co.","cite":"94 F. Supp. 2d 77","y":1999,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/94/77/","by":{"2":"30"}},{"t":"case","label":"Murphy v. Jefferson Pilot Commc’ns Co.","cite":"657 F. Supp. 2d 683","y":2008,"court":"D.S.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/657/683/","by":{"2":"30"}},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"op":1,"sum":"To give effect to § 5322(a)'s \"willfulness\" requirement, the Government must prove that the defendant acted with knowledge that the structuring he or she undertook was unlawful, not simply that the defendant's purpose was to circumvent a bank's reporting obligation. Section 5324 itself forbids structuring with a \"purpose of evading the [§ 5313(a)] reporting requirements,\" and the lower courts erred in treating the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17, 24"}},{"t":"case","label":"Reno v. Bossier Parish Sch. Bd.","cite":"528 U.S. 320","y":2000,"id":"1998/98-405","sc":1,"op":1,"ar":1,"sum":"The Court held that section 5 does not prohibit preclearance of a redistricting plan enacted with a discriminatory but nonretrogressive purpose. \"As we have repeatedly noted, in vote-dilution cases [section 5] prevents nothing but backsliding, and preclearance under [section 5] affirms nothing but the absence of backsliding,\" wrote Justice Scalia.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Ross v. Blake","cite":"136 S. Ct. 1850","y":2016,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Rumsfeld v. Padilla","cite":"542 U.S. 426","y":2004,"id":"2003/03-1027","sc":1,"op":1,"sum":"Explaining that the “use of the definite article . . . indicates that there is generally only one” person covered.","sumSrc":"opinion","by":{"2":"29"}},{"t":"case","label":"Sherwood v. Sutton","cite":"21 F. Cas. 1303","y":1828,"court":"C.C.D.N.H.","url":"https://www.courtlistener.com/c/F.%20Cas./21/1303/","by":{"2":"24"}},{"t":"case","label":"United States ex rel. Touhy v. Ragen","cite":"340 U.S. 462","y":1951,"id":"scdb/1950-037","sc":1,"sum":"Order No. 3229 is valid and the subordinate official properly refused to produce the papers.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"26"}},{"t":"const","label":"Article II, Section 2, Clause 2","clauses":[["treaty","Treaty Clause"],["appointments","Appointments Clause"]],"text":"He shall have Power, by and with the Advice and Consent of the Senate, to make Treaties, provided two thirds of the Senators present concur; and he shall nominate, and by and with the Advice and Consent of the Senate, shall appoint Ambassadors, other public Ministers and Consuls, Judges of the supreme Court, and all other Officers of the United States, whose Appointments are not herein otherwise provided for, and which shall be established by Law: but the Congress may by Law vest the Appointment of such inferior Officers, as they think proper, in the President alone, in the Courts of Law, or in the Heads of Departments.","by":{"2":"28"}},{"t":"law","label":"Dodd-Frank Wall Street Reform and Consumer Protection Act, Pub. L. No. 111-203","url":"https://www.govinfo.gov/link/plaw/111/public/203","by":{"2":"15"}},{"t":"usc","label":"28 U.S.C. § 510","url":"https://www.law.cornell.edu/uscode/text/28/510","by":{"2":"28"}},{"t":"rule","label":"Fed. R. Civ. P. 17","url":"https://www.law.cornell.edu/rules/frcp/rule_17","subs":["(a)"],"by":{"2":"30"}},{"t":"case","label":"Burnett v. N.Y. Cent. R.R. Co.","cite":"380 U.S. 424","y":1965,"id":"1964/437","sc":1,"sum":"Where a timely FELA action is begun in a state court having jurisdiction, the defendant is served with process, and the case is dismissed for improper venue, the FELA time limitation is tolled during the pendency of the state suit and until the state court order dismissing the action becomes final. Pp. 426-436. 332 F. 2d 529, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"9"}},{"t":"case","label":"Chao v. Va. Dep’t of Transp.","cite":"291 F.3d 276","y":2002,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/291/276/","by":{"3":"8"}},{"t":"case","label":"China Agritech, Inc. v. Resh","cite":"138 S. Ct. 1800","y":2018,"id":"2017/17-432","sc":1,"sum":"The Court decided that upon denial of class certification, a putative class member may not, in lieu of promptly joining an existing suit or promptly filing a individual action, commence a class action anew beyond the time allowed by the applicable statute of limitations.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"case","label":"Nat’l Cable & Telecomms. Ass’n v. Brand X Internet Servs.","cite":"545 U.S. 967","y":2005,"id":"2004/04-277","sc":1,"op":1,"sum":"The Court held that the FCC lawfully construed the Communications Act to not define cable broadband providers as \"telecommunications services.\" The Court held that the Ninth Circuit should have followed the Supreme Court's 1984 decision in Chevron v. Natural Resources Defense Council.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"United States ex rel. Salmeron v. Enter. Recovery Sys., Inc.","cite":"464 F. Supp. 2d 766","y":2006,"court":"N.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/464/766/","by":{"3":"13"}},{"t":"case","label":"Will v. Mich. Dep’t of State Police","cite":"491 U.S. 58","y":1989,"id":"1988/87-1207","sc":1,"sum":"Neither States nor state officials acting in their official capacities are \"persons\" within meaning of § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"6"}},{"t":"usc","label":"15 U.S.C. § 77m","url":"https://www.law.cornell.edu/uscode/text/15/77m","by":{"3":"8"}},{"t":"usc","label":"28 U.S.C. § 1658","url":"https://www.law.cornell.edu/uscode/text/28/1658","subs":["(b)"],"by":{"3":"9"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"3":"6, 11"}}]};